From 97c3acd5c88f8d18d12a15921fece6aee893860a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 03:04:40 +0100
Subject: [PATCH] applet: let distributions override the defaults of main.xml

Applets now embed main.xml, so distributions can't patch it to change
defaults like the Task Manager's pinned apps. The groups and keys of a
plasma-<plugin id>-defaultsrc file in the XDG config dirs replace them.

BUG: 511560
---
 src/plasma/applet.cpp | 59 ++++++++++++++++++++++++++++++++++++++++++-
 1 file changed, 58 insertions(+), 1 deletion(-)

diff --git a/src/plasma/applet.cpp b/src/plasma/applet.cpp
index dd2a9f667..782a4268c 100644
--- a/src/plasma/applet.cpp
+++ b/src/plasma/applet.cpp
@@ -10,13 +10,17 @@
 #include "applet.h"
 #include "private/applet_p.h"

+#include <QBuffer>
 #include <QDebug>
 #include <QFile>
 #include <QJSEngine>
 #include <QList>
 #include <QMetaEnum>
+#include <QXmlStreamReader>
+#include <QXmlStreamWriter>

 #include <KAuthorized>
+#include <KConfig>
 #include <KConfigLoader>
 #include <KConfigPropertyMap>
 #include <KGlobalAccel>
@@ -33,6 +37,7 @@

 #include <cmath>
 #include <limits>
+#include <optional>

 namespace Plasma
 {
@@ -229,6 +234,50 @@ bool Applet::destroyed() const
     return d->transient;
 }

+// Replaces the defaults of main.xml with the values of the same group and key in the defaults file
+static void applyDefaults(QIODevice *xml, const KConfig &defaults, QIODevice *out)
+{
+    xml->open(QIODevice::ReadOnly);
+    out->open(QIODevice::WriteOnly);
+    QXmlStreamReader reader(xml);
+    QXmlStreamWriter writer(out);
+    QString group;
+    std::optional<QString> defaultValue;
+
+    auto isElement = [&reader](QLatin1String name) {
+        return reader.name().compare(name, Qt::CaseInsensitive) == 0;
+    };
+
+    while (!reader.atEnd()) {
+        reader.readNext();
+        if (reader.isStartElement() && isElement(QLatin1String("group"))) {
+            group = reader.attributes().value(QLatin1String("name")).toString();
+        } else if (reader.isStartElement() && isElement(QLatin1String("entry"))) {
+            QString key = reader.attributes().value(QLatin1String("key")).trimmed().toString();
+            if (key.isEmpty()) {
+                key = reader.attributes().value(QLatin1String("name")).trimmed().toString();
+            }
+            const KConfigGroup cg = defaults.group(group);
+            defaultValue.reset();
+            if (!group.isEmpty() && cg.hasKey(key)) {
+                defaultValue = cg.readEntry(key, QString());
+            }
+        } else if (defaultValue && reader.isStartElement() && isElement(QLatin1String("default"))) {
+            writer.writeTextElement(QStringLiteral("default"), *defaultValue);
+            defaultValue.reset();
+            reader.skipCurrentElement();
+            continue;
+        } else if (defaultValue && reader.isEndElement() && isElement(QLatin1String("entry"))) {
+            writer.writeTextElement(QStringLiteral("default"), *defaultValue);
+            defaultValue.reset();
+        }
+        writer.writeCurrentToken(reader);
+    }
+
+    xml->close();
+    out->close();
+}
+
 KConfigLoader *Applet::configScheme() const
 {
     if (!d->configLoader) {
@@ -248,7 +297,15 @@ KConfigLoader *Applet::configScheme() const
             d->configLoader = new KConfigLoader(cfg, nullptr);
         } else {
             QFile file(xmlPath);
-            d->configLoader = new KConfigLoader(cfg, &file);
+            // Distributions can change the defaults with a plasma-<plugin id>-defaultsrc file in the XDG config dirs
+            const KConfig defaults(QLatin1String("plasma-%1-defaultsrc").arg(pluginMetaData().pluginId()), KConfig::NoGlobals);
+            if (defaults.groupList().isEmpty()) {
+                d->configLoader = new KConfigLoader(cfg, &file);
+            } else {
+                QBuffer buffer;
+                applyDefaults(&file, defaults, &buffer);
+                d->configLoader = new KConfigLoader(cfg, &buffer);
+            }
             QObject::connect(d->configLoader, SIGNAL(configChanged()), this, SLOT(propagateConfigChanged()));
         }
     }
